import JSZip from 'https://esm.sh/jszip@3.10.1';
const cfg=window.ZUQUI_CARDAPIO_CONFIG||{};
let token=localStorage.getItem('zuqui_admin_token')||'',refreshToken=localStorage.getItem('zuqui_admin_refresh')||'',state={},tab='products',filters={contains:'',group:'',groupId:'',onlyActiveGroups:false,onlyActive:false},selectedProducts=new Set(),filterTimer;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.addEventListener('click',e=>{const button=e.target.closest('[data-category-editorial]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();openCategoryEditor(button.dataset.categoryEditorial)},true);
async function api(action,body={}){if(!cfg.apiUrl)throw new Error('Informe apiUrl em cardapio-config.js após implantar o servidor.');const r=await fetch(cfg.apiUrl,{method:'POST',headers:{'content-type':'application/json',...(token?{authorization:`Bearer ${token}`}:{})},body:JSON.stringify({action,...body})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Falha na operação.');return j}
const apiRequest=api;
async function refreshSession(){if(!refreshToken)return false;const r=await fetch(cfg.apiUrl,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'refresh_session',refresh_token:refreshToken})}),j=await r.json().catch(()=>({}));if(!r.ok)return false;token=j.access_token;refreshToken=j.refresh_token||refreshToken;localStorage.setItem('zuqui_admin_token',token);localStorage.setItem('zuqui_admin_refresh',refreshToken);return true}
api=async function(action,body={},retry=true){if(action==='link_connector')action='link_connector_v2';try{return await apiRequest(action,body)}catch(error){if(retry&&token&&!['login','login_v2','refresh_session'].includes(action)&&await refreshSession())return api(action,body,false);throw error}};
async function load(){const[snapshot,catalogStatus]=await Promise.all([api('admin_snapshot'),api('catalog_status')]),products=[];for(let page=0;;page++){const r=await api('catalog_products_page',{page});products.push(...r.products);if(r.products.length<1000)break}state={...snapshot,products,catalogStatus};$('loginView').hidden=true;$('appView').hidden=false;renderMenuAvailability();render()}
function renderMenuAvailability(){const active=!!state.ordering_enabled,host=$('menuAvailability');host.classList.toggle('active',active);host.innerHTML=`<div><h2>${active?'CARDÁPIO ATIVADO':'CARDÁPIO DESATIVADO'}</h2><p>${active?'Clientes podem adicionar produtos e lançar pedidos.':'Clientes podem consultar os produtos, mas não podem adicionar nem lançar pedidos.'}</p></div><button id="toggleMenuAvailability" class="${active?'danger':''}">${active?'DESATIVAR CARDÁPIO':'ATIVAR CARDÁPIO'}</button>`;$('toggleMenuAvailability').onclick=async()=>{const next=!active;if(!confirm(`${next?'Ativar':'Desativar'} o cardápio agora?`))return;const button=$('toggleMenuAvailability');button.disabled=true;button.textContent='Salvando...';try{await api('set_ordering',{enabled:next});await load()}catch(error){button.disabled=false;button.textContent=active?'DESATIVAR CARDÁPIO':'ATIVAR CARDÁPIO';alert(error.message)}}}
$('changeForm').onsubmit=async e=>{e.preventDefault();if($('newPassword').value!==$('confirmPassword').value)return $('changeMsg').textContent='As senhas não coincidem.';try{await api('change_password',{password:$('newPassword').value});$('changeView').hidden=true;await load()}catch(x){$('changeMsg').textContent=x.message}};
$('tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));render()};
const list=(items,title,kind)=>`<div class="toolbar"><h2>${title}</h2><button data-new="${kind}">Adicionar</button></div><div class="grid">${items.map(x=>`<article class="item"><div><b>${esc(x.name||x.label||x.guid)}</b><p>${esc(x.description||x.status||'')}</p></div><div class="actions"><button data-edit="${kind}" data-id="${x.id}">Editar</button></div></article>`).join('')||'<p>Nenhum cadastro.</p>'}</div>`;
function render(){if(tab==='products')products();if(tab==='banners')banners();if(tab==='sync')syncPanel();if(tab==='cards')cards();if(tab==='references')references();if(tab==='orders')orders();if(tab==='integration')integration()}
function cards(){$('content').innerHTML=`<section class="card">${list(state.cards||[],'Comandas virtuais','card')}<p class="status">O QR usa um token aleatório de 256 bits. O número e o código virtual da comanda não ficam visíveis no QR.</p></section>`;document.querySelectorAll('[data-edit="card"]').forEach(b=>b.insertAdjacentHTML('afterend',`<button data-card-qr="${b.dataset.id}">Gerar QR seguro</button>`))}
function references(){$('content').innerHTML=`<section class="card"><div class="toolbar"><h2>Mesas e setores de impressão</h2><button data-new="reference">Adicionar mesa</button></div><div class="grid">${(state.references||[]).map(x=>`<article class="item"><div><b>${esc(x.name)}</b><p>Setor de impressão Raffinato: <strong>${esc(x.print_sector_id||'não definido')}</strong></p></div><div class="actions"><button data-reference-config="${x.id}">Editar mesa</button><button data-reference-qr="${x.id}">Gerar QR da mesa</button></div></article>`).join('')||'<p>Nenhuma mesa cadastrada.</p>'}</div><p class="status">Informe o ID criado em Vendas → Configuração → Setor de Impressão no Raffinato. Um ID inválido será ignorado pelo próprio Raffinato.</p></section>`}
async function showQr(value,title){const d=$('qrDialog'),number=(title.match(/\d+/)||[])[0],printTitle=/comanda/i.test(title)?`COMANDA ${number||title}`:`MESA ${number||title}`,$download=$('qrDownload');$('qrTitle').textContent=printTitle;$('qrImage').src=await labeledQr(value,printTitle);$('qrValue').textContent=value;$download.href=$('qrImage').src;$download.download=`${printTitle.replace(/\s+/g,'-').toLowerCase()}.png`;d.showModal()}
function effective(p){const g=(state.categories||[]).find(x=>x.id===p.category_id);if(!state.catalogStatus?.connectors?.some(x=>x.active&&x.store_id))return[false,'Loja sem conector vinculado'];if(!p.source_available||!p.available)return[false,'Indisponível na origem'];if(!g?.digital_enabled)return[false,'Grupo desativado'];if(p.cardapio_override===false)return[false,'Excluído individualmente'];return[true,p.cardapio_override===true?'Ativado individualmente':'Ativo pelo grupo']}
function products(){const groups=state.categories||[],needle=filters.contains.toLocaleLowerCase('pt-BR'),items=(state.products||[]).filter(p=>(!needle||`${p.source_name||p.name} ${p.source_barcode||''} ${p.raffinato_product_id||''}`.toLocaleLowerCase('pt-BR').includes(needle))&&(!filters.group||p.category_id===filters.group)&&(!filters.onlyActive||effective(p)[0]));$('content').innerHTML=`<section class="card"><div class="toolbar"><h2>Grupos e produtos</h2><span>${items.length} de ${(state.products||[]).length}</span></div><div class="form-grid filters"><label>Contém<input id="filterContains" value="${esc(filters.contains)}" placeholder="Nome, código de barras ou ID"></label><label>Grupo inteiro — não inclui subgrupos<select id="filterGroup"><option value="">Todos os grupos</option>${groups.map(g=>`<option value="${g.id}" ${filters.group===g.id?'selected':''}>${esc(g.source_name||g.name)}</option>`).join('')}</select></label><label class="wide"><input id="filterActive" type="checkbox" ${filters.onlyActive?'checked':''}> Somente ativos no cardápio</label></div><div class="bulk-actions"><button id="selectVisible">Selecionar visíveis</button><button id="clearSelection" class="ghost">Limpar seleção</button><button id="activateSelected">Ativar selecionados</button><button id="deactivateSelected" class="danger">Desativar selecionados</button><b>${selectedProducts.size} selecionado(s)</b></div><div class="groups">${groups.map(g=>`<button data-group-toggle="${g.id}" data-enabled="${!g.digital_enabled}">${g.digital_enabled?'Desativar':'Ativar'} grupo: ${esc(g.source_name||g.name)}</button>`).join('')}</div><div class="grid">${items.map(p=>{const[on,reason]=effective(p);return`<article class="item ${on?'enabled':'disabled'}"><label class="select-product"><input type="checkbox" data-select-product="${p.id}" ${selectedProducts.has(p.id)?'checked':''}><span>Selecionar</span></label><div><b>${esc(p.source_name||p.name)}</b><p>${esc(p.source_barcode||'Sem código')} · ID ${p.raffinato_product_id} · ${esc(p.source_category_name||'Sem grupo')}</p><strong>R$ ${Number(p.source_price??p.price).toFixed(2).replace('.',',')}</strong><p class="source">Sincronizado ${p.source_updated_at?new Date(p.source_updated_at).toLocaleString('pt-BR'):'-'}</p><p><b>${on?'ATIVO':'NÃO APARECE'}</b> — ${esc(reason)}</p>${on?`<p>${esc(p.description||'Sem descrição')}</p>`:''}</div><div class="actions"><button data-product-toggle="${p.id}" data-enabled="${!on}">${on?'Desativar':'Ativar'} produto</button>${on?`<button data-editorial="${p.id}">Foto e descrição</button>`:''}</div></article>`}).join('')||'<p>Nenhum produto encontrado.</p>'}</div></section>`;for(const id of['filterContains','filterGroup','filterActive'])$(id).oninput=()=>{filters={contains:$('filterContains').value,group:$('filterGroup').value,onlyActive:$('filterActive').checked};products()};$('selectVisible').onclick=()=>{items.forEach(x=>selectedProducts.add(x.id));products()};$('clearSelection').onclick=()=>{selectedProducts.clear();products()};$('activateSelected').onclick=()=>bulkProducts(true);$('deactivateSelected').onclick=()=>bulkProducts(false)}
async function bulkProducts(enabled){const ids=[...selectedProducts];if(!ids.length)return alert('Selecione pelo menos um produto.');if(!confirm(`${enabled?'Ativar':'Desativar'} ${ids.length} produto(s) selecionado(s)?`))return;for(let i=0;i<ids.length;i+=500)await api('set_products_override',{ids:ids.slice(i,i+500),enabled});selectedProducts.clear();await load();if(enabled)alert('Produtos ativados individualmente. Eles aparecerão quando os respectivos grupos também estiverem ativos.')}
function syncPanel(){const s=state.catalogStatus||{},c=(s.connectors||[])[0],store=(s.stores||[]).find(x=>x.id===c?.store_id),r=(s.runs||[])[0];$('content').innerHTML=`<section class="card"><div class="toolbar"><h2>Loja e conector Raffinato</h2><button id="syncNow" ${c?.connection_tested_at?'':'disabled'}>Sincronizar agora</button></div><p class="status ${c?.connection_tested_at?'ok':'bad'}"><b>Loja:</b> ${esc(store?.name||'Não vinculada')}<br><b>Instalação:</b> ${esc(c?.installation_name||'-')} (${c?.installation_id?esc(c.installation_id.slice(0,8))+'…':'-'})<br><b>Filial Raffinato:</b> ${esc(c?.raffinato_branch_id||'-')}<br><b>Conexão:</b> ${c?.connection_tested_at?'testada em '+new Date(c.connection_tested_at).toLocaleString('pt-BR'):'teste pendente'}<br><b>Último contato:</b> ${c?.last_seen_at?new Date(c.last_seen_at).toLocaleString('pt-BR'):'-'}</p>${c?.connection_test_error?`<p class="status bad">${esc(c.connection_test_error)}</p>`:''}<div class="form-grid"><label>Loja<select id="linkStore">${(s.stores||[]).map(x=>`<option value="${x.id}" ${x.id===c?.store_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Filial Raffinato<input id="linkBranch" type="number" min="1" value="${esc(c?.raffinato_branch_id||1)}"></label><label class="wide">Instalação<select id="linkInstallation">${(s.connectors||[]).map(x=>`<option value="${x.installation_id}">${esc(x.installation_name)} · ${esc(x.installation_id.slice(0,8))}…</option>`).join('')}</select></label><button id="linkConnector">Vincular loja e instalação</button></div><p>O token permanece somente no conector e no servidor. Após alterar o vínculo, execute o teste de conexão no servidor antes de sincronizar.</p><p>Última sincronização: ${r?`${new Date(r.started_at).toLocaleString('pt-BR')} · ${esc(r.status)} · ${r.processed} produtos`:'nenhuma'}.</p><div class="grid">${(s.runs||[]).map(x=>`<article class="item"><div><b>${new Date(x.started_at).toLocaleString('pt-BR')} · ${esc(x.status)}</b><p>${x.processed} processados<br>${esc(x.error_message||'')}</p></div></article>`).join('')}</div></section>`;if(c)$('syncNow').onclick=async()=>{await api('catalog_sync_request',{connector_id:c.id});alert('Solicitação registrada.');await load()};$('linkConnector').onclick=async()=>{await api('link_connector',{store_id:$('linkStore').value,installation_id:$('linkInstallation').value,branch_id:Number($('linkBranch').value)});alert('Vínculo salvo. Execute o teste de conexão no servidor.');await load()}}
function orders(){$('content').innerHTML=`<section class="card"><div class="toolbar"><h2>Pedidos e retornos</h2><button id="refresh">Atualizar</button></div><div class="grid">${(state.orders||[]).map(o=>`<article class="item"><div><b>${esc(o.status)} · ${new Date(o.created_at).toLocaleString('pt-BR')}</b><p class="order-meta">GUID ${esc(o.guid)}<br>Comanda ${esc(o.card_label)} · Referência ${esc(o.reference_name)}<br>idvenda ${esc(o.idvenda||'-')} · numeropedido ${esc(o.numeropedido||'-')}<br>${esc(o.error_message||'')}</p></div></article>`).join('')||'<p>Nenhum pedido.</p>'}</div></section>`}
function integration(){const i=state.integration||{};$('content').innerHTML=`<section class="card"><h2>Integração de pedidos Raffinato</h2><p class="status ${i.ready?'ok':'bad'}">${i.ready?'Configuração técnica completa. Pedidos públicos continuam dependendo de ativação explícita.':'Faltam URL completa/porta, método HTTP, autenticação e conectividade com a rede privada.'}</p><p>A sincronização do catálogo é independente deste envio de pedidos.</p><div class="form-grid"><label class="wide">URL completa da rota /RecebePedidos<input id="endpoint" value="${esc(i.endpoint_url)}" placeholder="Não conhecida"></label><label>Método HTTP<input id="method" value="${esc(i.http_method)}" placeholder="Não conhecido"></label><label>Tipo de autenticação<input id="authType" value="${esc(i.auth_type)}" placeholder="Não conhecido"></label><label class="wide">Observações<textarea id="notes">${esc(i.notes)}</textarea></label></div><button id="saveIntegration">Salvar informações não secretas</button><hr><section class="card test"><h3>Primeiro teste controlado</h3><p>Comanda 4 · MESA 04 · garçom 20 · produto 451 · R$ 6,70.</p><button id="testOrder" ${i.ready?'':'disabled'}>Enviar um único pedido de teste</button><p id="testMsg"></p></section><hr><label><input id="enabled" type="checkbox" ${state.ordering_enabled?'checked':''} ${i.test_validated?'':'disabled'}> Habilitar pedidos públicos</label></section>`;$('saveIntegration').onclick=saveIntegration;$('testOrder').onclick=testOrder;$('enabled').onchange=async e=>{await api('set_ordering',{enabled:e.target.checked});await load()}}
async function saveIntegration(){await api('save_integration',{endpoint_url:$('endpoint').value,http_method:$('method').value,auth_type:$('authType').value,notes:$('notes').value});await load()}
async function testOrder(){if(!confirm('Enviar agora o pedido único de teste para a comanda 4?'))return;try{$('testOrder').disabled=true;const r=await api('test_order');$('testMsg').textContent=`Resultado: ${r.status}. ${r.message||''}`;await load()}catch(e){$('testMsg').textContent=e.message}}
document.addEventListener('click',async e=>{if(e.target.id==='refresh')return load();if(e.target.dataset.groupToggle){await api('set_category_enabled',{id:e.target.dataset.groupToggle,enabled:e.target.dataset.enabled==='true'});return load()}if(e.target.dataset.productToggle){await api('set_product_override',{id:e.target.dataset.productToggle,enabled:e.target.dataset.enabled==='true'});return load()}if(e.target.dataset.editorial){const p=(state.products||[]).find(x=>x.id===e.target.dataset.editorial);await api('update_product_editorial',{id:p.id,description:prompt('Descrição para o cliente',p.description||'')||'',image_url:prompt('URL da foto',p.image_url||'')||null,sort_order:Number(prompt('Ordem de exibição',p.sort_order||0)||0),featured:confirm('Marcar como destaque?')});return load()}if(e.target.dataset.referenceQr){const x=(state.references||[]).find(v=>v.id===e.target.dataset.referenceQr);return showQr(`${location.origin}/cardapio/?reference=${encodeURIComponent(x.id)}`,`Mesa / referência ${x.name}`)}if(e.target.dataset.cardQr){const x=(state.cards||[]).find(v=>v.id===e.target.dataset.cardQr),r=await api('generate_card_claim',{card_id:x.id});return showQr(`${location.origin}/cardapio/?claim=${encodeURIComponent(r.token)}`,`Comanda ${x.label}`)}const kind=e.target.dataset.new||e.target.dataset.edit;if(!kind)return;const current=(state[kind+'s']||state.categories||[]).find(x=>x.id===e.target.dataset.id)||{};const name=prompt(`Nome de ${kind}`,current.name||current.label||'');if(!name)return;await api('upsert_entity',{kind,id:current.id,name,label:name,available:true,sort_order:Number(current.sort_order||0)});await load()});
document.addEventListener('change',e=>{if(!e.target.dataset.selectProduct)return;e.target.checked?selectedProducts.add(e.target.dataset.selectProduct):selectedProducts.delete(e.target.dataset.selectProduct);const counter=document.querySelector('.bulk-actions b');if(counter)counter.textContent=`${selectedProducts.size} selecionado(s)`});
bulkProducts=async function(enabled){const ids=[...selectedProducts];if(!ids.length)return alert('Selecione pelo menos um produto.');if(!confirm(`${enabled?'Ativar':'Desativar'} ${ids.length} produto(s) selecionado(s)?`))return;try{for(let i=0;i<ids.length;i+=500)await api('set_products_override',{ids:ids.slice(i,i+500),enabled});selectedProducts.clear();await load();alert(enabled?'Produtos e respectivos grupos ativados. Somente os produtos selecionados foram ativados.':'Produtos selecionados desativados.')}catch(error){alert(error.message)}};
products=function(){const groups=state.categories||[],needle=filters.contains.toLocaleLowerCase('pt-BR'),items=(state.products||[]).filter(p=>(!needle||`${p.display_name||''} ${p.source_name||p.name||''} ${p.source_barcode||''} ${p.raffinato_product_id||''}`.toLocaleLowerCase('pt-BR').includes(needle))&&(!filters.group||p.category_id===filters.group)&&(!filters.onlyActive||effective(p)[0]));$('content').innerHTML=`<section class="card"><div class="toolbar"><h2>Grupos e produtos</h2><span>${items.length} de ${(state.products||[]).length}</span></div><div class="form-grid filters"><label>Contém<input id="filterContains" value="${esc(filters.contains)}" placeholder="Nome no cardápio, nome original, código ou ID"></label><label>Grupo inteiro - nao inclui subgrupos<select id="filterGroup"><option value="">Todos os grupos</option>${groups.map(g=>`<option value="${g.id}" ${filters.group===g.id?'selected':''}>${esc(g.display_name||g.source_name||g.name)}</option>`).join('')}</select></label><label class="wide"><input id="filterActive" type="checkbox" ${filters.onlyActive?'checked':''}> Somente ativos no cardapio</label></div><div class="bulk-actions"><button id="selectVisible">Selecionar visiveis</button><button id="clearSelection" class="ghost">Limpar selecao</button><button id="activateSelected">Ativar selecionados</button><button id="deactivateSelected" class="danger">Desativar selecionados</button><b>${selectedProducts.size} selecionado(s)</b></div><div class="groups">${groups.map(g=>`<span class="group-control"><button data-group-toggle="${g.id}" data-enabled="${!g.digital_enabled}">${g.digital_enabled?'Desativar':'Ativar'} grupo: ${esc(g.display_name||g.source_name||g.name)}</button><button class="ghost" data-category-editorial="${g.id}">Editar</button></span>`).join('')}</div><div class="grid">${items.map(p=>{const[on,reason]=effective(p);return`<article class="item ${on?'enabled':'disabled'}"><label class="select-product"><input type="checkbox" data-select-product="${p.id}" ${selectedProducts.has(p.id)?'checked':''}><span>Selecionar</span></label><div><b>${p.display_name?`Nome Cardápio - ${esc(p.display_name)}`:esc(p.source_name||p.name)}</b>${p.display_name?`<p>Original: ${esc(p.source_name||p.name)}</p>`:''}<p>${esc(p.source_barcode||'Sem codigo')} · ID ${p.raffinato_product_id} · ${esc(p.source_category_name||'Sem grupo')}</p><strong>R$ ${Number(p.source_price??p.price).toFixed(2).replace('.',',')}</strong><p class="source">Sincronizado ${p.source_updated_at?new Date(p.source_updated_at).toLocaleString('pt-BR'):'-'}</p><p><b>${on?'ATIVO':'NAO APARECE'}</b> - ${esc(reason)}</p>${on?`<p>${esc(p.description||'Sem descricao')}</p>`:''}</div><div class="actions"><button data-product-toggle="${p.id}" data-enabled="${!on}">${on?'Desativar':'Ativar'} produto</button>${on?`<button data-editorial="${p.id}">Editar</button>`:''}</div></article>`}).join('')||'<p>Nenhum produto encontrado.</p>'}</div></section>`;const search=$('filterContains');search.oninput=()=>{filters.contains=search.value;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{const position=search.selectionStart;products();requestAnimationFrame(()=>{const next=$('filterContains');next.focus();next.setSelectionRange(position,position)})},180)};$('filterGroup').onchange=e=>{filters.group=e.target.value;products()};$('filterActive').onchange=e=>{filters.onlyActive=e.target.checked;products()};$('selectVisible').onclick=()=>{items.forEach(x=>selectedProducts.add(x.id));products()};$('clearSelection').onclick=()=>{selectedProducts.clear();products()};$('activateSelected').onclick=()=>bulkProducts(true);$('deactivateSelected').onclick=()=>bulkProducts(false)};
document.addEventListener('click',async e=>{const editorial=e.target.closest('[data-editorial]'),categoryButton=e.target.closest('[data-category-editorial]');if(!editorial&&!categoryButton)return;e.preventDefault();e.stopImmediatePropagation();try{if(editorial){const p=(state.products||[]).find(x=>x.id===editorial.dataset.editorial),displayName=prompt('Nome visivel ao cliente (vazio usa o nome do Raffinato)',p.display_name||p.source_name||p.name);if(displayName===null)return;const description=prompt('Descricao para o cliente',p.description||'');if(description===null)return;const image=prompt('URL da foto',p.image_url||'');if(image===null)return;await api('update_product_editorial',{id:p.id,display_name:displayName,description,image_url:image||null,sort_order:Number(p.sort_order||0),featured:!!p.featured})}else{const g=(state.categories||[]).find(x=>x.id===categoryButton.dataset.categoryEditorial),displayName=prompt('Nome do grupo visivel ao cliente (vazio usa o Raffinato)',g.display_name||g.source_name||g.name);if(displayName===null)return;const description=prompt('Descricao do grupo para o cliente',g.description||'');if(description===null)return;await api('update_category_editorial',{id:g.id,display_name:displayName,description,sort_order:Number(g.sort_order||0)})}await load()}catch(error){alert(error.message)}},true);
document.addEventListener('click',async e=>{const product=e.target.closest('[data-product-toggle]'),group=e.target.closest('[data-group-toggle]');if(!product&&!group)return;e.preventDefault();e.stopImmediatePropagation();const button=product||group,label=button.textContent;button.disabled=true;button.textContent='Salvando...';try{if(product)await api('set_product_override',{id:product.dataset.productToggle,enabled:product.dataset.enabled==='true'});else await api('set_category_enabled',{id:group.dataset.groupToggle,enabled:group.dataset.enabled==='true'});await load()}catch(error){button.disabled=false;button.textContent=label;alert(`Nao foi possivel salvar: ${error.message}`)}},true);

// Busca exclusiva de agrupamentos por "contém". Não mistura nomes de produtos,
